import type { EngineInterface, Register } from "claude-code";
import { update } from "claude-code";

import type { Room, WorkspaceTree } from "../types";
import {
	accessPath,
	cliConfigPath,
	connectedBy,
	connectKept,
	connectLaunched,
	connectSaved,
	drawn,
	follow,
	here,
	isClient,
	isReachable,
	LEVERAGE_TOOLS,
	leverageRequest,
	MIRRORED,
	space,
} from "./client";
import { registerCommands } from "./commands";
import { PANE, registerPane } from "./pane";
import { registerPeople } from "./people";

// Makes this Claude Code session a client of one Leverage session. The turn
// runs in the Leverage sandbox. This process draws it and never calls a model.

type Block =
	| { kind: "text"; text: string }
	| { kind: "thinking"; text: string }
	| {
			kind: "tool";
			id: string;
			name: string;
			input: Record<string, unknown>;
			/** The Leverage subagent the call started. */
			agent?: {
				task: string;
				description: string;
				prompt: string;
				type: string | null;
			};
	  };
type Waiting = {
	writable: boolean;
	approvals: { id: string; tool: string; input: unknown }[];
	question: string | null;
};
type Step =
	| {
			blocks: Block[];
			stop: "tool_use" | "end_turn";
			cursor: number;
			turnId: string | null;
			/** The tokens the Leverage session's context holds. */
			context: number | null;
			question: string | null;
	  }
	| {
			pending: true;
			waiting?: Waiting;
			/** The text the agent is writing, which no row holds yet. */
			live?: { id: string; kind: "text" | "reasoning"; text: string }[];
	  };
type Result =
	| { content: string; isError: boolean }
	| { pending: true; progress?: string; seen?: number };

// Remote tools with a local twin whose output shape the mod can build.
const NATIVE = new Set(["Bash", "Read", "Edit", "Write"]);
const usage = (context: number | null) => ({
	input_tokens: context ?? 0,
	output_tokens: 0,
	cache_creation_input_tokens: 0,
	cache_read_input_tokens: 0,
	model: "leverage",
});
/** The window's status line: the session's title, or its space. */
let shown = "Leverage";
/** The rows already shown as notices, by position. */
const noticed = new Set<number>();
/** The background commands still running, by task id. */
const running = new Set<string>();
/** The people the last prompt poll saw, as sent, so an unchanged room draws nothing. */
let seenRoom = "";
/** Prompts asked to wait, still in Claude Code's queue, oldest first. */
const waiting: { text: string; skills: { name: string }[]; pasted: boolean }[] =
	[];

/** The subagents Claude Code is starting for Leverage, until each has its id. */
const spawning = new Set<Promise<unknown>>();

/** The status line: the session, and what runs in the background. */
function line(): string {
	return running.size > 0
		? `${shown} · ${running.size} in the background`
		: shown;
}
const CHOICES = ["Once", "This session", "Always", "Reject"];
const DECISIONS: Record<string, string> = {
	Once: "once",
	"This session": "session",
	Always: "always",
	Reject: "reject",
};

async function call<T>(
	$: EngineInterface,
	path: string,
	body?: unknown,
): Promise<T> {
	const res = await $.http.fetch(...leverageRequest(path, body));
	if (!res.ok) {
		throw new Error(
			res.status === 401
				? connectedBy() === "launched"
					? "Leverage refused this Claude Code token. Run leverage claude again."
					: "Leverage refused this Claude Code token. /leverage login signs in again."
				: `Leverage answered ${res.status}: ${res.text}`,
		);
	}
	return JSON.parse(res.text) as T;
}

// The session's title, or its space until the first prompt starts one.
async function showLabel($: EngineInterface) {
	let label = "";
	if (here.id) {
		label = (await call<{ title: string }>($, `/sessions/${here.id}`)).title;
	} else if (space()) {
		const tree = await call<WorkspaceTree>($, "/workspace");
		const channel = tree.channels.find((one) => one.id === space());
		label = channel ? `#${channel.name}` : "";
	}
	// The engine shows the plugin name before the line.
	shown = label || "Leverage";
	$.ui.status(line());
}

// Asks each call that waits on this person, in Claude Code's own dialog.
async function askApprovals($: EngineInterface, waiting: Waiting) {
	for (const pending of waiting.approvals) {
		if (here.known.has(pending.id)) continue;
		here.known.add(pending.id);
		if (!waiting.writable) {
			$.ui.status(`${shown} · waiting for approval of ${pending.tool}`);
			continue;
		}
		let answer: string;
		try {
			answer = await $.ui.ask(
				`Allow ${pending.tool} to run in Leverage? ${JSON.stringify(pending.input).slice(0, 300)}`,
				{ header: "Approval", options: CHOICES },
			);
		} catch {
			$.ui.toast("Not decided. /leverage approvals asks again.");
			continue;
		}
		// Text typed under Other rejects the call, and Leverage passes it on.
		const decision = DECISIONS[answer] ?? "reject";
		await call($, `/approvals/${pending.id}`, {
			decision,
			...(DECISIONS[answer] ? {} : { reason: answer }),
		});
	}
}

// Reads the session's last turns into one notice, so an opened window has context.
async function showHistory($: EngineInterface) {
	const { messages } = await call<{
		messages: { author: string; text: string }[];
	}>($, `/sessions/${here.id}/history`);
	if (messages.length === 0) return;
	const text = messages
		.map((message) => `${message.author}: ${message.text}`)
		.join("\n\n");
	await $.session.append({
		message: {
			type: "system",
			content: [{ type: "text", text: `Earlier in this session:\n\n${text}` }],
		},
	});
}

// Sends a prompt of this window. The first one starts the session, named
// here so a retried start makes no second one.
async function send(
	$: EngineInterface,
	prompt: {
		text: string;
		images: { filename: string; dataUrl: string }[];
		skills: { name: string }[];
		steer?: boolean;
	},
) {
	const uuid = crypto.randomUUID();
	drawn.add(uuid);
	if (here.id) {
		await call($, `/sessions/${here.id}/messages`, { ...prompt, uuid });
		return;
	}
	const { steer: _, ...first } = prompt;
	const started = await call<{ id: string; cursor: number }>($, "/sessions", {
		id: crypto.randomUUID(),
		channelId: space(),
		...first,
		uuid,
	});
	follow(started.id, started.cursor);
	await showLabel($);
}

// Opens the session in this window: its history, and it reads as read.
async function open($: EngineInterface) {
	await call($, `/sessions/${here.id}/read`, {});
	await showHistory($);
}

function localName(name: string): string {
	// Claude Code asks it in its own dialog.
	if (NATIVE.has(name) || name === "AskUserQuestion") return name;
	const short = name.replace(/^mcp__leverage__/, "");
	return MIRRORED.includes(short)
		? `mcp__leverage__${short}`
		: "mcp__leverage__remote_tool";
}

function localInput(name: string, block: Extract<Block, { kind: "tool" }>) {
	return localName(name) === "mcp__leverage__remote_tool"
		? { name: block.name, input: block.input }
		: block.input;
}

function lines(text: string): string[] {
	return text === "" ? [] : text.split("\n");
}

// The images of the prompt just added to this session, as data URLs.
async function lastImages($: EngineInterface) {
	const messages = await $.session.messages({ as: "api" });
	const prompt = [...messages]
		.reverse()
		.find((message) => message.role === "user");
	return (prompt?.content ?? []).flatMap((block, index) => {
		const source = block.source as
			| { type?: string; media_type?: string; data?: string }
			| undefined;
		if (block.type !== "image" || source?.type !== "base64") return [];
		return [
			{
				filename: `image-${index + 1}.${source.media_type?.split("/")[1] ?? "png"}`,
				dataUrl: `data:${source.media_type};base64,${source.data}`,
			},
		];
	});
}

// Where an edit's new text starts in its file, read back from the session.
async function editLine($: EngineInterface, input: Record<string, unknown>) {
	const path = String(input.file_path ?? "");
	const after = String(input.new_string ?? "");
	if (!path.startsWith("/work/") || !after) return 1;
	try {
		const file = await call<{ content?: string }>(
			$,
			`/sessions/${here.id}/file?path=${encodeURIComponent(path.slice("/work/".length))}`,
		);
		const at = file.content?.indexOf(after) ?? -1;
		return at < 0 ? 1 : (file.content ?? "").slice(0, at).split("\n").length;
	} catch {
		return 1;
	}
}

/** Above this many line pairs an edit draws as all removed, then all added. */
const DIFF_LIMIT = 250_000;

// The lines both sides keep show as context; the rest as removed and added.
function lineDiff(before: string[], after: string[]): string[] {
	const n = before.length;
	const m = after.length;
	if (n * m > DIFF_LIMIT) {
		return [...before.map((l) => `-${l}`), ...after.map((l) => `+${l}`)];
	}
	// kept[i][j]: how many lines the rest of both sides have in common.
	const kept = Array.from({ length: n + 1 }, () =>
		new Array<number>(m + 1).fill(0),
	);
	for (let i = n - 1; i >= 0; i--) {
		for (let j = m - 1; j >= 0; j--) {
			kept[i]![j] =
				before[i] === after[j]
					? kept[i + 1]![j + 1]! + 1
					: Math.max(kept[i + 1]![j]!, kept[i]![j + 1]!);
		}
	}
	const out: string[] = [];
	let i = 0;
	let j = 0;
	while (i < n || j < m) {
		if (i < n && j < m && before[i] === after[j]) {
			out.push(` ${before[i]}`);
			i++;
			j++;
		} else if (i < n && (j === m || kept[i + 1]![j]! >= kept[i]![j + 1]!)) {
			out.push(`-${before[i]}`);
			i++;
		} else {
			out.push(`+${after[j]}`);
			j++;
		}
	}
	return out;
}

// Builds the output shape each native tool's schema demands. `line` is where
// an edit starts in its file.
function nativeResult(
	tool: string,
	input: Record<string, unknown>,
	content: string,
	line = 1,
) {
	const path = String(input.file_path ?? "");
	switch (tool) {
		case "Bash":
			return { stdout: content, stderr: "", interrupted: false };
		case "Read": {
			const body = content.replace(/^\s*\d+\t/gm, "");
			const count = lines(body).length;
			return {
				type: "text",
				file: {
					filePath: path,
					content: body,
					numLines: count,
					startLine: Number(input.offset ?? 1),
					totalLines: count,
				},
			};
		}
		case "Edit": {
			const before = lines(String(input.old_string ?? ""));
			const after = lines(String(input.new_string ?? ""));
			return {
				filePath: path,
				oldString: String(input.old_string ?? ""),
				newString: String(input.new_string ?? ""),
				originalFile: null,
				structuredPatch: [
					{
						oldStart: line,
						oldLines: before.length,
						newStart: line,
						newLines: after.length,
						lines: lineDiff(before, after),
					},
				],
				userModified: false,
				replaceAll: input.replace_all === true,
			};
		}
		case "Write":
			return {
				type: "create",
				filePath: path,
				content: String(input.content ?? ""),
				structuredPatch: [],
				originalFile: null,
			};
	}
	return content;
}

/** The token `/leverage login` keeps in Claude Code's config; or "{}". */
async function savedAccess($: EngineInterface): Promise<string> {
	const file = accessPath(
		await $.env.get("CLAUDE_CONFIG_DIR"),
		await $.env.get("HOME"),
	);
	return file ? $.fs.read(file).catch(() => "{}") : "{}";
}

/** The Leverage CLI's config, where it keeps its Claude Code token; or "{}". */
async function keptConfig($: EngineInterface): Promise<string> {
	const file = cliConfigPath(
		await $.env.get("LEVERAGE_CONFIG_DIR"),
		await $.env.get("XDG_CONFIG_HOME"),
		await $.env.get("HOME"),
	);
	return file ? $.fs.read(file).catch(() => "{}") : "{}";
}

export const register: Register = (on) => {
	registerPane(on);
	registerCommands(on);
	registerPeople(on);

	on("session.start", async ($, e, next) => {
		const result = await next(e);
		await $.command.register({
			name: "leverage",
			description: "The Leverage session: pane, approvals, files, model…",
			argumentHint: "[help]",
		});
		const launched = connectLaunched({
			url: await $.env.get("LEVERAGE_CLAUDE_URL"),
			token: await $.env.get("LEVERAGE_CLAUDE_TOKEN"),
			space: await $.env.get("LEVERAGE_CLAUDE_SPACE"),
			session: await $.env.get("LEVERAGE_CLAUDE_SESSION"),
		});
		// Any other window, as Claude Desktop's, takes the token /leverage login
		// keeps, or the one the Leverage CLI keeps.
		if (!launched && !connectSaved(await savedAccess($)))
			connectKept(await keptConfig($));
		if (launched) {
			for (const tool of LEVERAGE_TOOLS) await $.tool.register(tool);
			// A window opened on a session starts at its newest row.
			if (here.id) {
				const opened = await call<{ id: string; cursor: number }>(
					$,
					`/sessions/${here.id}`,
				);
				follow(opened.id, opened.cursor);
				await open($);
			}
			await showLabel($);
		}
		if (isReachable()) void $.ui.open({ id: PANE, title: "Leverage" });
		// Turns started from another client open a turn here, so both show it.
		// The poll runs from the start, so a later /leverage login needs no restart.
		$.clock.every(1500, async () => {
			if (!isClient() || !here.id) return;
			const { prompts, notices, last, viewers, typing } = await call<
				{
					prompts: {
						uuid: string;
						author: string;
						text: string;
						images: number;
						steer: boolean;
					}[];
					notices: {
						seq: number;
						text: string;
						task?: { id: string; running: boolean };
					}[];
					last: number;
				} & Room
			>($, `/sessions/${here.id}/prompts?after=${here.polled}`);
			here.polled = Math.max(here.polled, last);
			// An older Leverage sends no room.
			const room: Room = { viewers: viewers ?? [], typing: typing ?? [] };
			if (JSON.stringify(room) !== seenRoom) {
				seenRoom = JSON.stringify(room);
				await update($, { plugin: "leverage", key: "people" }, () => room);
			}
			// A row the window does not draw, as a compaction, shows as a notice.
			for (const notice of notices) {
				if (noticed.has(notice.seq)) continue;
				noticed.add(notice.seq);
				if (notice.task?.running) running.add(notice.task.id);
				else if (notice.task) running.delete(notice.task.id);
				$.ui.status(line());
				await $.session
					.append({
						message: {
							type: "system",
							content: [{ type: "text", text: notice.text }],
						},
					})
					.catch(() => {});
			}
			for (const p of prompts) {
				if (drawn.has(p.uuid)) continue;
				drawn.add(p.uuid);
				// A teammate's steer joins the running turn; Claude Code only shows it.
				if (p.steer) {
					await $.session
						.append({
							message: {
								type: "system",
								content: [
									{
										type: "text",
										text: `${p.author} (in Leverage) adds: ${p.text}`,
									},
								],
							},
						})
						.catch(() => {});
					continue;
				}
				// Claude Code takes no image from a plugin, so the prompt says it has some.
				const images =
					p.images > 0
						? ` [${p.images} image${p.images > 1 ? "s" : ""} in Leverage]`
						: "";
				await $.prompt.submit({
					text: `${p.author} (in Leverage): ${p.text}${images}`,
					asUser: true,
				});
			}
		});
		return result;
	});

	on("prompt.submit", async ($, e, next) => {
		if (!isClient()) return next(e);
		// Only what a person writes goes to Leverage. A plugin's prompt is a
		// teammate's, already sent, unless it carries a skill.
		const person = e.origin.kind === "composer" || e.origin.kind === "bridge";
		// Leverage's turn took a subagent's report already; no turn reads it here.
		const report =
			[...here.loops.keys()].some((id) =>
				e.text.includes(`<agent-message from="${id}">`),
			) ||
			[...here.agents.keys()].some((id) =>
				e.text.includes(`<tool-use-id>${id}</tool-use-id>`),
			);
		if (!person && report) {
			return { drop: "Leverage's turn has the subagent's report." };
		}
		if (!person && !(e.origin.kind === "plugin" && here.skill)) {
			return next(e);
		}
		const skills = here.skill ? [{ name: here.skill }] : [];
		here.skill = null;
		// A sent prompt ends the typing the others see.
		if (here.typedAt && here.id) {
			here.typedAt = 0;
			void call($, `/sessions/${here.id}/typing`, { active: false }).catch(
				() => {},
			);
		}
		const pasted =
			e.attachments?.some((item) => item.type === "image") ?? false;
		// Asked to wait (ctrl+x enter), it stays in Claude Code's queue, where it
		// can be taken back, and goes to Leverage when its own turn starts.
		if (e.turnId && e.wait) {
			waiting.push({ text: e.text, skills, pasted });
			return next(e);
		}
		// Typed over a running turn, it steers that turn in Leverage too. Its
		// images enter the session only later, so a steer goes without them.
		const steer = Boolean(e.turnId);
		const result = pasted && !steer ? await next(e) : null;
		const images = pasted && !steer ? await lastImages($) : [];
		await send($, { text: e.text, images, skills, steer });
		return result ?? next(e);
	});

	// A prompt that waited in Claude Code's queue goes when its turn starts.
	on("turn.start", async ($, e, next) => {
		const result = await next(e);
		if (!isClient()) return result;
		const at = waiting.findIndex((one) => one.text === e.text);
		if (at < 0) return result;
		const [prompt] = waiting.splice(at, 1);
		if (!prompt) return result;
		const images = prompt.pasted ? await lastImages($) : [];
		await send($, { text: prompt.text, images, skills: prompt.skills });
		return result;
	});

	// Esc here stops the turn in the sandbox too.
	on("turn.complete", async ($, e, next) => {
		if (isClient() && here.id && e.reason === "aborted") {
			here.skip = here.turnId;
			await call($, `/sessions/${here.id}/stop`, {});
		}
		return next(e);
	});

	// The Leverage session holds the context, so it compacts, not this window.
	on("session.compact", async ($, e, next) => {
		if (!isClient()) return next(e);
		if (e.trigger !== "manual" || !here.id) {
			return { skip: "The Leverage session compacts itself." };
		}
		await call($, `/sessions/${here.id}/compact`, {});
		return { skip: "Leverage is compacting this session." };
	});

	// One window shows one Leverage session, so these act on Leverage.
	on("command.run", { command: "rename" }, async ($, e, next) => {
		if (!isClient() || !here.id) return next(e);
		const title = e.args.trim();
		if (!title) return { text: "Name the session: /rename <title>" };
		await call($, `/sessions/${here.id}/rename`, { title });
		await showLabel($);
		return { text: `Renamed the Leverage session to ${title}.` };
	});
	on("command.run", { command: "resume" }, ($, e, next) =>
		isClient()
			? { text: "/leverage opens another Leverage session in this window." }
			: next(e),
	);

	// Claude Code runs a Leverage subagent as its own agent. Its steps come
	// from the subagent's rows in Leverage.
	on("agent.spawn", async ($, e, next) => {
		const subagent = here.agents.get(e.tool_use_id);
		if (!isClient() || !subagent) return next(e);
		// In the foreground, as in Leverage: the turn goes on once it ends.
		const started = next({ ...e, background: false });
		spawning.add(started);
		try {
			const spawned = await started;
			if (spawned.agentId) here.loops.set(spawned.agentId, subagent);
			return spawned;
		} finally {
			spawning.delete(started);
		}
	});

	// Leverage ran the subagent already, so Claude Code asks nobody about it.
	on("tool.check", { tool: "Agent" }, ($, e, next) =>
		isClient() && here.agents.has(e.tool_use_id ?? "")
			? { decision: "allow" }
			: next(e),
	);

	on("turn.step", async function* ($, e, next) {
		if (!isClient()) return yield* next(e);
		// A subagent's first step can come before its spawn names it.
		if (e.agentId && !here.loops.has(e.agentId))
			await Promise.allSettled([...spawning]);
		const subagent = e.agentId ? here.loops.get(e.agentId) : undefined;
		if (e.agentId && !subagent) return yield* next(e);
		let step: Exclude<Step, { pending: true }>;
		// Each message drawn as it arrives, at the block index it took.
		const streamed: {
			id: string;
			kind: "text" | "thinking";
			text: string;
			index: number;
		}[] = [];
		let index = 0;
		for (;;) {
			if (next.signal.aborted) throw new Error("aborted");
			const skip = here.skip ? `&skip=${here.skip}` : "";
			const known =
				here.known.size > 0 ? `&known=${[...here.known].join(",")}` : "";
			const drawn = streamed.map((entry) => `${entry.id}:${entry.text.length}`);
			const shown =
				drawn.length > 0 ? `&shown=${encodeURIComponent(drawn.join(","))}` : "";
			// A subagent's rows are stored whole, so its steps do not stream.
			const answer = await call<Step>(
				$,
				subagent
					? `/sessions/${here.id}/step?after=${subagent.cursor}&task=${encodeURIComponent(subagent.task)}${known}`
					: `/sessions/${here.id}/step?after=${here.cursor}&stream=true${skip}${known}${shown}`,
			);
			if (!("pending" in answer)) {
				step = answer;
				break;
			}
			if (answer.waiting) await askApprovals($, answer.waiting);
			for (const live of answer.live ?? []) {
				let entry = streamed.find((one) => one.id === live.id);
				if (!entry) {
					const kind = live.kind === "reasoning" ? "thinking" : "text";
					entry = { id: live.id, kind, text: "", index: index++ };
					streamed.push(entry);
				}
				if (!live.text.startsWith(entry.text)) continue;
				const piece = live.text.slice(entry.text.length);
				entry.text = live.text;
				if (piece) yield { kind: entry.kind, index: entry.index, text: piece };
			}
		}
		if (subagent) {
			subagent.cursor = step.cursor;
			if (step.question) here.question = step.question;
		} else {
			here.cursor = step.cursor;
			here.turnId = step.turnId;
			here.question = step.question;
			// A first turn names the session.
			if (step.stop === "end_turn") void showLabel($);
		}
		let answer = "";
		const toolUses: { name: string; input: unknown }[] = [];
		let matched = 0;
		for (const block of step.blocks) {
			if (block.kind === "text" || block.kind === "thinking") {
				if (block.kind === "text") answer += block.text;
				// A message streamed already gets the rest of its text.
				const rest = streamed.slice(matched);
				const entry = rest.find((one) => one.kind === block.kind);
				if (entry && block.text.startsWith(entry.text)) {
					matched = streamed.indexOf(entry) + 1;
					const piece = block.text.slice(entry.text.length);
					if (piece)
						yield { kind: block.kind, index: entry.index, text: piece };
				} else {
					yield { kind: block.kind, index: index++, text: block.text };
				}
			} else {
				const name = block.agent ? "Agent" : localName(block.name);
				const input = block.agent
					? {
							description: block.agent.description || "Leverage subagent",
							prompt: block.agent.prompt,
							// Explore runs in the background; Leverage's subagents block their turn.
							subagent_type: "general-purpose",
						}
					: localInput(name, block);
				if (block.agent) {
					here.agents.set(block.id, {
						task: block.agent.task,
						cursor: step.cursor,
					});
				}
				here.calls.add(block.id);
				toolUses.push({ name, input });
				yield { kind: "tool", index, id: block.id, name };
				yield { kind: "input", index: index++, json: JSON.stringify(input) };
			}
		}
		// A subagent ends its run in Claude Code by handing its report back.
		let stop = step.stop;
		if (subagent && stop === "end_turn") {
			const input = { message: answer || "Done." };
			toolUses.push({ name: "SubagentHandback", input });
			const id = `toolu_handback_${subagent.task.replace(/\W/g, "_")}`;
			yield { kind: "tool", index, id, name: "SubagentHandback" };
			yield { kind: "input", index: index++, json: JSON.stringify(input) };
			stop = "tool_use";
		}
		yield { kind: "stop", stopReason: stop, usage: usage(step.context) };
		return {
			turnId: e.turnId,
			index: e.index,
			answer,
			toolUses,
			stopReason: stop,
			usage: usage(step.context),
		};
	});

	on("tool.call", async ($, e, next) => {
		const id = e.tool_use_id ?? "";
		// Registered tools stay offered after logout; none runs then.
		if (!isClient() && e.tool.startsWith("mcp__leverage__"))
			return { deny: "This window is not connected to Leverage." };
		if (!isClient() || !here.calls.has(id)) return next(e);
		// Claude Code runs the subagent; its steps come from Leverage.
		if (here.agents.has(id)) return next(e);
		const asked = here.question === id;
		if (asked) here.question = null;
		if (e.tool === "AskUserQuestion" && asked) {
			// Claude Code asks it; Leverage takes the answers as the web app does.
			const answered = await next(e);
			const answers =
				(answered as { result?: { answers?: Record<string, string> } }).result
					?.answers ?? {};
			// Answered in another app meanwhile: Leverage keeps that answer.
			await call($, `/sessions/${here.id}/answers`, {
				toolUseId: id,
				answers,
			}).catch(() => {});
			return answered;
		}
		if (e.tool === "mcp__leverage__ExitPlanMode" && asked) {
			const answer = await $.ui
				.ask("Approve this plan?", {
					header: "Plan",
					options: ["Approve", "Request changes"],
				})
				.catch(() => "");
			if (answer) {
				const plan = answer === "Approve" ? "approved" : "changes_requested";
				await call($, `/sessions/${here.id}/answers`, {
					toolUseId: id,
					answers: { plan },
				});
			}
		}
		const name = String(e.tool).replace(/^mcp__leverage__/, "");
		$.ui.status(`${line()} · ${name} runs in Leverage`);
		// The tool's own progress shows on the status line until its result.
		let seen = 0;
		let result: Exclude<Result, { pending: true }>;
		for (;;) {
			if (next.signal.aborted) throw new Error("aborted");
			const answer = await call<Result>(
				$,
				`/sessions/${here.id}/results/${encodeURIComponent(id)}?stream=true&seen=${seen}`,
			);
			if (!("pending" in answer)) {
				result = answer;
				break;
			}
			if (answer.progress !== undefined) {
				seen = answer.seen ?? seen;
				const progress = answer.progress.trim().split("\n").at(-1) ?? "";
				$.ui.status(`${line()} · ${name}: ${progress.slice(0, 120)}`);
			}
		}
		$.ui.status(line());
		if (e.tool === "AskUserQuestion") {
			// Answered in another app: the answers read as that app's reply.
			const input = e as { questions?: unknown[] };
			return {
				result: {
					questions: input.questions ?? [],
					answers: {},
					response: result.content,
				} as never,
			};
		}
		if (result.isError) return { deny: result.content };
		const { tool, tool_use_id: _, ...input } = e as Record<string, unknown>;
		const startLine = tool === "Edit" ? await editLine($, input) : 1;
		const shaped = NATIVE.has(String(tool))
			? nativeResult(String(tool), input, result.content, startLine)
			: result.content;
		return { result: shaped as never };
	});
};

files.hooks/client.ts:
import type { HttpInit } from "claude-code";

// Where this window reaches Leverage, shared by the plugin's modules. Each
// module calls $.http.fetch itself: the engine follows $ only within one file.

export type Connection = {
	/** The app origin. The plugin's routes are under `/api/claude`. */
	url: string;
	/** A Claude Code token, which names the person and the workspace. */
	token: string;
	/** The space whose first prompt starts a session. */
	space: string | null;
};

/** Where Leverage is, unless LEVERAGE_HOST names another. */
const PRODUCTION = "https://app.leverage.computer";

let connection: Connection | null = null;
/** Where the connection came from: `leverage claude`, `/leverage login` or the CLI's config. */
let source: "launched" | "saved" | "kept" | null = null;

/** The session this window shows, and the last row it read. */
export const here = {
	id: "",
	cursor: 0,
	turnId: null as string | null,
	/** A turn stopped here. Its remaining rows are not drawn. */
	skip: null as string | null,
	/** Approvals this window already asked, so none is asked twice. */
	known: new Set<string>(),
	/** The question this person answers in Claude Code's own dialog. */
	question: null as string | null,
	/** The tool calls the remote turn made. Any other call runs here. */
	calls: new Set<string>(),
	/** The last row the prompt and notice poll read. */
	polled: 0,
	/** A skill the next prompt sent from this window loads. */
	skill: null as string | null,
	/** When this person last told Leverage they type; 0 when they do not. */
	typedAt: 0,
	/** Each Leverage subagent and the last row of it drawn, by its Agent call. */
	agents: new Map<string, Subagent>(),
	/** The same subagents, by the Claude Code agent that runs each. */
	loops: new Map<string, Subagent>(),
};

/** A Leverage subagent that Claude Code runs as its own agent. */
export type Subagent = { task: string; cursor: number };

/** The prompts this window sent or already drew. */
export const drawn = new Set<string>();

/** Whether this window runs a Leverage session's turns, not only the pane. */
let isClientWindow = false;

/**
 * Takes the connection `leverage claude` starts Claude Code with. Such a
 * window runs a session's turns at once.
 */
export function connectLaunched(env: {
	url: string | undefined;
	token: string | undefined;
	space: string | undefined;
	session: string | undefined;
}): boolean {
	if (!env.url || !env.token) return false;
	connection = {
		url: env.url.replace(/\/+$/, ""),
		token: env.token,
		space: env.space || null,
	};
	if (env.session) here.id = env.session;
	source = "launched";
	isClientWindow = true;
	return true;
}

/**
 * Takes the Claude Code token the Leverage CLI keeps in its config, so any
 * window, as Claude Desktop's, lists the sessions in the pane. The window
 * runs a session's turns only once the person opens one there.
 */
export function connectKept(config: string): boolean {
	const kept = keptToken(config);
	if (!kept) return false;
	connection = { ...kept, space: null };
	source = "kept";
	return true;
}

/** The Claude Code token in the Leverage CLI's config, and its host; or null. */
export function keptToken(
	config: string,
): { url: string; token: string } | null {
	let parsed: {
		currentHost?: string;
		hosts?: Record<
			string,
			{
				workspaceId?: string;
				accessTokens?: Record<string, Record<string, string>>;
			}
		>;
	};
	try {
		parsed = JSON.parse(config);
	} catch {
		return null;
	}
	const hosts = parsed.hosts ?? {};
	// The signed-in host first, then any other that keeps one.
	for (const host of [parsed.currentHost, ...Object.keys(hosts)]) {
		if (!host) continue;
		const profile = hosts[host];
		const token = profile?.workspaceId
			? profile.accessTokens?.claude?.[profile.workspaceId]
			: undefined;
		if (!token) continue;
		return { url: host.replace(/\/+$/, ""), token };
	}
	return null;
}

/**
 * Takes the token `/leverage login` saved in Claude Code's config. Like the
 * CLI's, it lists the sessions in the pane until the person opens one.
 */
export function connectSaved(saved: string): boolean {
	let parsed: { url?: string; token?: string };
	try {
		parsed = JSON.parse(saved);
	} catch {
		return false;
	}
	if (!parsed.url || !parsed.token) return false;
	connection = {
		url: parsed.url.replace(/\/+$/, ""),
		token: parsed.token,
		space: null,
	};
	source = "saved";
	return true;
}

const isAbsolute = (path: string) => /^(\/|[A-Za-z]:[\\/])/.test(path);

/**
 * The file `/leverage login` keeps its token in, in Claude Code's config; or
 * null with no home folder, so no token is ever read from or left in a project.
 */
export function accessPath(
	configDir: string | undefined,
	home: string | undefined,
): string | null {
	const dir = configDir || (home ? `${home}/.claude` : "");
	return isAbsolute(dir) ? `${dir}/leverage.json` : null;
}

/** The Leverage CLI's config file; or null with no home folder. */
export function cliConfigPath(
	configDir: string | undefined,
	xdg: string | undefined,
	home: string | undefined,
): string | null {
	const dir =
		configDir ||
		(xdg ? `${xdg}/leverage` : home ? `${home}/.config/leverage` : "");
	return isAbsolute(dir) ? `${dir}/config.json` : null;
}

/** The Leverage `/leverage login` signs in to: LEVERAGE_HOST's, or the app. */
export function leverageHost(named: string | undefined): string {
	const host = named?.trim();
	if (!host) return PRODUCTION;
	try {
		const url = new URL(/^[a-z]+:\/\//i.test(host) ? host : `https://${host}`);
		return /^https?:$/.test(url.protocol) ? url.origin : PRODUCTION;
	} catch {
		return PRODUCTION;
	}
}

/** Leaves Leverage: this window is Claude Code's own again. */
export function disconnect() {
	connection = null;
	source = null;
	isClientWindow = false;
	follow("", 0);
}

/** From now on, this window runs the turns of the session it follows. */
export function becomeClient() {
	isClientWindow = true;
}

// Remote tools drawn as tools of this mod. Others go to `remote_tool`.
export const MIRRORED = [
	"Grep",
	"Glob",
	"Task",
	"Agent",
	"TodoWrite",
	"WebFetch",
	"WebSearch",
	"NotebookEdit",
	"Skill",
	"ExitPlanMode",
	"ToolSearch",
	"leverage_execute",
];

/** The tools a window that runs Leverage's turns registers, as registered. */
export const LEVERAGE_TOOLS = [...MIRRORED, "remote_tool"].map((name) => ({
	name,
	description: `${name}, run by the Leverage session.`,
	inputSchema: { type: "object" as const, additionalProperties: true },
}));

/** Whether the pane and /leverage can reach Leverage. */
export function isReachable(): boolean {
	return connection !== null;
}

export function connectedBy() {
	return source;
}

/** Whether this window runs a Leverage session's turns. */
export function isClient(): boolean {
	return connection !== null && isClientWindow;
}

export function space(): string | null {
	return connection?.space ?? null;
}

/** Moves this window to a session. Later steps read after `cursor`. */
export function follow(id: string, cursor: number) {
	here.id = id;
	here.cursor = cursor;
	here.polled = cursor;
	here.turnId = null;
	here.skip = null;
	here.known.clear();
	here.question = null;
	here.typedAt = 0;
	here.agents.clear();
	here.loops.clear();
}

export function leverageRequest(
	path: string,
	body?: unknown,
): [string, HttpInit] {
	if (!connection) throw new Error("This window is not connected to Leverage.");
	return [
		`${connection.url}/api/claude${path}`,
		{
			method: body === undefined ? "GET" : "POST",
			headers: {
				authorization: `Bearer ${connection.token}`,
				"content-type": "application/json",
			},
			body: body === undefined ? undefined : JSON.stringify(body),
		},
	];
}

files.hooks/commands.ts:
import type { EngineInterface, HttpResponse, On, Timer } from "claude-code";
import { update } from "claude-code";

import {
	accessPath,
	cliConfigPath,
	connectedBy,
	connectSaved,
	disconnect,
	here,
	isReachable,
	keptToken,
	leverageHost,
	leverageRequest,
	space,
} from "./client";
import { PANE } from "./pane";

// `/leverage <action>`: what the other Leverage apps do with a session,
// done on the session this window shows. Bare, it opens the pane.

const HELP = `/leverage                 open the pane: spaces and their sessions
/leverage login [workspace]  sign in in the browser
/leverage logout          forget the token here
/leverage approvals       ask again for calls that wait on you
/leverage rename <title>  rename this session (/rename does too)
/leverage archive         archive this session; restore brings it back
/leverage model [id] [effort]  show or pick the session's model
/leverage queue           prompts other apps queued for this session
/leverage queue take <n>  take a waiting prompt back
/leverage queue send <n>  send a waiting prompt now
/leverage outputs         files the last turn wrote
/leverage files [path]    this session's files, or the space's
/leverage find <name>     find a file of this session by name
/leverage read <path>     show a file of this session
/leverage save <path>     save a file of this session here
/leverage run <command>   run a shell command in the session's sandbox
/leverage changes         each repository's changes and pull request
/leverage skills          the skills this session can load
/leverage skill <name> <prompt>  send a prompt that loads a skill
/leverage connectors      the workspace's connectors
/leverage history [more]  the session's last turns, then older ones`;

/** The most a file shows in the transcript. */
const SHOWN_CHARS = 20_000;
/** Where the next older page of history starts, once one was shown. */
let olderFrom: number | null = null;

async function call<T>(
	$: EngineInterface,
	path: string,
	body?: unknown,
): Promise<T> {
	const res = await $.http.fetch(...leverageRequest(path, body));
	if (res.status === 401)
		throw new Error(
			connectedBy() === "launched"
				? "Leverage refused this token. Run leverage claude again."
				: "Leverage refused this token. /leverage login signs in again.",
		);
	if (!res.ok) {
		const reason = (() => {
			try {
				return (JSON.parse(res.text) as { error?: string }).error;
			} catch {
				return undefined;
			}
		})();
		throw new Error(reason ?? `Leverage answered ${res.status}`);
	}
	return JSON.parse(res.text) as T;
}

type Approval = { id: string; tool: string; input: unknown };
type Waiting = { writable: boolean; approvals: Approval[] };
type Model = { id: string; label: string; efforts: string[] };
type Entry = { path: string; type?: string };
type FileRead = { content?: string; isBinary?: boolean; truncated?: boolean };

const quoted = (path: string) => encodeURIComponent(path);

async function approvals($: EngineInterface): Promise<string> {
	const waiting = await call<Waiting>($, `/sessions/${here.id}/waiting`);
	if (waiting.approvals.length === 0) return "No call waits for approval.";
	if (!waiting.writable) return "Calls wait for the session owner's approval.";
	for (const pending of waiting.approvals) {
		const answer = await $.ui
			.ask(
				`Allow ${pending.tool} to run in Leverage? ${JSON.stringify(pending.input).slice(0, 300)}`,
				{
					header: "Approval",
					options: ["Once", "This session", "Always", "Reject"],
				},
			)
			.catch(() => "");
		if (!answer) continue;
		here.known.add(pending.id);
		const decision =
			{ Once: "once", "This session": "session", Always: "always" }[answer] ??
			"reject";
		await call($, `/approvals/${pending.id}`, {
			decision,
			...(answer === "Reject" || decision !== "reject"
				? {}
				: { reason: answer }),
		});
	}
	return "Decided.";
}

async function model($: EngineInterface, args: string[]): Promise<string> {
	const [id, effort] = args;
	if (id) {
		await call($, `/sessions/${here.id}/model`, {
			model: id,
			...(effort ? { effort } : {}),
		});
		return `The session runs ${id}${effort ? ` at ${effort}` : ""} from the next turn.`;
	}
	const [models, session] = await Promise.all([
		call<Model[]>($, "/models"),
		call<{ model: string | null; effort: string | null }>(
			$,
			`/sessions/${here.id}`,
		),
	]);
	const lines = models.map(
		(one) =>
			`${one.id === session.model ? "●" : "○"} ${one.id}  ${one.label}${one.efforts.length ? `  (${one.efforts.join(", ")})` : ""}`,
	);
	return [
		`Now: ${session.model ?? "the space's default"}${session.effort ? ` at ${session.effort}` : ""}`,
		...lines,
		"Pick one: /leverage model <id> [effort]",
	].join("\n");
}

async function queue($: EngineInterface, args: string[]): Promise<string> {
	const items = await call<{ uuid: string; text: string }[]>(
		$,
		`/sessions/${here.id}/queue`,
	);
	const [action, number] = args;
	if (!action) {
		if (items.length === 0) return "No prompt waits.";
		return items
			.map((item, index) => `${index + 1}. ${item.text.slice(0, 120)}`)
			.join("\n");
	}
	const item = items[Number(number) - 1];
	if (!item) return `No waiting prompt ${number ?? ""}.`;
	if (action === "take") {
		await call($, `/sessions/${here.id}/queue/${item.uuid}/cancel`, {});
		return "Taken back.";
	}
	if (action === "send") {
		await call($, `/sessions/${here.id}/queue/${item.uuid}/send`, {});
		return "Sent now.";
	}
	return "Use: /leverage queue [take|send] <n>";
}

async function files($: EngineInterface, path: string): Promise<string> {
	const at = here.id
		? `/sessions/${here.id}/files?path=${quoted(path)}`
		: `/spaces/${space()}/files?path=${quoted(path)}`;
	const listed = await call<{ entries: Entry[]; truncated?: boolean }>($, at);
	if (listed.entries.length === 0) return "No files here.";
	const lines = listed.entries.map(
		(entry) => `${entry.path}${entry.type === "dir" ? "/" : ""}`,
	);
	return [...lines, ...(listed.truncated ? ["…more"] : [])].join("\n");
}

// A file of the session, or of the space before a session starts.
async function readFile($: EngineInterface, path: string): Promise<FileRead> {
	return call<FileRead>(
		$,
		here.id
			? `/sessions/${here.id}/file?path=${quoted(path)}`
			: `/spaces/${space()}/file?path=${quoted(path)}`,
	);
}

// Shows a file in the transcript, or saves it in the working folder.
async function readOrSave(
	$: EngineInterface,
	action: "read" | "save",
	path: string,
): Promise<string> {
	if (!path) return `Name the file: /leverage ${action} <path>`;
	const file = await readFile($, path);
	if (action === "save") {
		if (file.content === undefined) return "Leverage cannot read that file.";
		const name = path.split("/").at(-1) ?? "output";
		await $.fs.write(name, file.content);
		return `Saved ${name}.`;
	}
	if (file.isBinary || file.content === undefined)
		return "Not a text file. /leverage save keeps it here.";
	return file.content.length > SHOWN_CHARS
		? `${file.content.slice(0, SHOWN_CHARS)}\n…`
		: file.content;
}

async function run($: EngineInterface, args: string): Promise<string> {
	const [action = "", ...rest] = args.trim().split(/\s+/);
	const tail = args.trim().slice(action.length).trim();
	if (action === "help") return HELP;
	if (action === "connectors") {
		const connectors = await call<{ name: string; disabled: boolean }[]>(
			$,
			"/connectors",
		);
		return connectors.length === 0
			? "No connectors in this workspace."
			: connectors
					.map((one) => `${one.disabled ? "○" : "●"} ${one.name}`)
					.join("\n");
	}
	if (!here.id && action === "files") return files($, tail);
	if (!here.id && (action === "read" || action === "save"))
		return readOrSave($, action, tail);
	if (!here.id) return "Send a first prompt, or open a session with /leverage.";
	switch (action) {
		case "approvals":
			return approvals($);
		case "rename":
			if (!tail) return "Name the session: /leverage rename <title>";
			await call($, `/sessions/${here.id}/rename`, { title: tail });
			$.ui.status(tail);
			return `Renamed the session to ${tail}.`;
		case "archive":
			await call($, `/sessions/${here.id}/archive`, {});
			return "Archived. /leverage restore brings it back.";
		case "restore":
			await call($, `/sessions/${here.id}/restore`, {});
			return "Restored.";
		case "model":
			return model($, rest);
		case "queue":
			return queue($, rest);
		case "outputs": {
			const outputs = await call<string[]>($, `/sessions/${here.id}/outputs`);
			return outputs.length === 0
				? "The last turn wrote no files."
				: `${outputs.join("\n")}\n/leverage read <path> shows one; /leverage save <path> keeps it here.`;
		}
		case "files":
			return files($, tail);
		case "find": {
			if (!tail) return "Name part of the file: /leverage find <name>";
			const found = await call<string[]>(
				$,
				`/sessions/${here.id}/find?name=${quoted(tail)}`,
			);
			return found.length === 0 ? "No file matches." : found.join("\n");
		}
		case "read":
		case "save":
			return readOrSave($, action, tail);
		case "run": {
			if (!tail) return "Name the command: /leverage run <command>";
			const ran = await call<{ exitCode: number; output: string }>(
				$,
				`/sessions/${here.id}/run`,
				{ command: tail },
			);
			const output =
				ran.output.length > SHOWN_CHARS
					? `${ran.output.slice(-SHOWN_CHARS)}`
					: ran.output;
			return `${output}${output.endsWith("\n") || !output ? "" : "\n"}exit ${ran.exitCode}`;
		}
		case "changes": {
			const repos = await call<
				{
					name: string;
					branch: string | null;
					changes: {
						path: string;
						state: string;
						additions: number;
						deletions: number;
					}[];
					unpublished: number;
					pullRequest: {
						number: number;
						url: string;
						state: string;
						draft: boolean;
					} | null;
				}[]
			>($, `/sessions/${here.id}/changes`);
			if (repos.length === 0) return "This session has no repository.";
			return repos
				.map((repo) => {
					const head = `${repo.name}${repo.branch ? ` (${repo.branch})` : ""}`;
					const pr = repo.pullRequest
						? `PR #${repo.pullRequest.number} ${repo.pullRequest.draft ? "draft" : repo.pullRequest.state}: ${repo.pullRequest.url}`
						: "No pull request.";
					const changed = repo.changes.map(
						(change) =>
							`  ${change.state} ${change.path} +${change.additions} -${change.deletions}`,
					);
					const unpublished =
						repo.unpublished > 0
							? [`  ${repo.unpublished} change(s) not in the pull request`]
							: [];
					return [
						head,
						...(changed.length ? changed : ["  no changes"]),
						...unpublished,
						pr,
					].join("\n");
				})
				.join("\n\n");
		}
		case "skills": {
			const skills = await call<{ name: string; description: string }[]>(
				$,
				`/sessions/${here.id}/skills`,
			);
			return skills.length === 0
				? "No skills."
				: `${skills.map((one) => `${one.name}  ${one.description}`).join("\n")}\n/leverage skill <name> <prompt> sends a prompt that loads one.`;
		}
		case "skill": {
			const [name, ...words] = rest;
			const prompt = words.join(" ");
			if (!name || !prompt) return "Use: /leverage skill <name> <prompt>";
			// The prompt goes through this window, so Claude Code draws its turn.
			here.skill = name;
			await $.prompt.submit({ text: prompt, asUser: true });
			return `Sent with the ${name} skill.`;
		}
		case "history": {
			if (tail === "more" && olderFrom === null) return "No older turns.";
			const from = tail === "more" ? `&before=${olderFrom}` : "";
			const page = await call<{
				messages: { author: string; text: string }[];
				before: number | null;
			}>($, `/sessions/${here.id}/history?turns=5${from}`);
			olderFrom = page.before;
			const text = page.messages
				.map((message) => `${message.author}: ${message.text}`)
				.join("\n\n");
			return `${text || "No turns yet."}${page.before === null ? "" : "\n\n/leverage history more shows older turns."}`;
		}
	}
	return HELP;
}

// `/leverage login` and `/leverage logout`: the token this plugin keeps in
// Claude Code's config. Login signs in in the browser, as `leverage login`
// does, and trades that sign-in for a Claude Code token of one workspace.

type Grant = {
	device_code: string;
	user_code: string;
	expires_in: number;
	interval: number;
};
type Workspace = { id: string; slug: string; name: string };

/** The browser sign-in that waits for its approval, if one does. */
let waiting: Timer | null = null;
/** Counts sign-ins; login and logout move it on, so an older one keeps nothing. */
let attempt = 0;

function stopWaiting() {
	waiting?.cancel();
	waiting = null;
	attempt++;
}

async function accessFile($: EngineInterface): Promise<string | null> {
	return accessPath(
		await $.env.get("CLAUDE_CONFIG_DIR"),
		await $.env.get("HOME"),
	);
}

async function cliHasToken($: EngineInterface): Promise<boolean> {
	const file = cliConfigPath(
		await $.env.get("LEVERAGE_CONFIG_DIR"),
		await $.env.get("XDG_CONFIG_HOME"),
		await $.env.get("HOME"),
	);
	const config = file ? await $.fs.read(file).catch(() => "{}") : "{}";
	return keptToken(config) !== null;
}

function send(
	$: EngineInterface,
	url: string,
	body?: unknown,
	token?: string,
): Promise<HttpResponse> {
	return $.http.fetch(url, {
		method: body === undefined ? "GET" : "POST",
		headers: {
			"content-type": "application/json",
			...(token ? { authorization: `Bearer ${token}` } : {}),
		},
		body: body === undefined ? undefined : JSON.stringify(body),
	});
}

// Opens the approval page. Where no browser opens, the reply has the link.
async function browse($: EngineInterface, link: string) {
	for (const opener of ["open", "xdg-open"]) {
		const opened = await $.process
			.run([opener, link], { timeoutMs: 5000 })
			.catch(() => null);
		if (opened?.exitCode === 0) return;
	}
}

// Keeps the token where only this person reads it, and connects this window.
async function keep(
	$: EngineInterface,
	url: string,
	token: string,
	live: () => boolean,
): Promise<string> {
	const checked = await send(
		$,
		`${url}/api/claude/workspace`,
		undefined,
		token,
	);
	if (checked.status === 401) return "Leverage refused that token.";
	if (!checked.ok) return `Leverage answered ${checked.status}.`;
	const { workspace } = JSON.parse(checked.text) as { workspace: string };
	const file = await accessFile($);
	if (!file) return "No home folder to keep the token in.";
	if (!live()) return "";
	const saved = `${JSON.stringify({ url, token }, null, "\t")}\n`;
	// Windows keeps a profile's files to its owner, and has no sh.
	const written = /^[A-Za-z]:/.test(file)
		? await $.fs.write(file, saved).then(
				() => ({ exitCode: 0 }),
				() => null,
			)
		: await $.process
				.run(
					[
						"/bin/sh",
						"-c",
						'umask 077 && mkdir -p "$(dirname "$1")" && cat > "$1" && chmod 600 "$1"',
						"sh",
						file,
					],
					{ stdin: saved },
				)
				.catch(() => null);
	if (written?.exitCode !== 0) return `Could not keep the token in ${file}.`;
	if (!live()) {
		await $.process.run(["rm", "-f", file]).catch(() => null);
		return "";
	}
	// A new token may name another workspace: nothing of the last one stays.
	disconnect();
	await update($, { plugin: "leverage", key: "tree" }, () => null);
	connectSaved(saved);
	void $.ui.open({ id: PANE, title: "Leverage" });
	return `Signed in to ${workspace}. /leverage opens the pane.`;
}

// The workspace named, the only one, or the one the person picks.
async function choose(
	$: EngineInterface,
	workspaces: Workspace[],
	named: string,
): Promise<Workspace | string> {
	if (named) {
		const found =
			workspaces.find((one) => one.slug === named) ??
			workspaces.find((one) => one.name === named);
		return found ?? `No workspace ${named}.`;
	}
	if (workspaces.length === 1) return workspaces[0] as Workspace;
	// Claude Code's dialog shows four at most.
	if (workspaces.length > 4) {
		const slugs = workspaces.map((one) => one.slug).join(", ");
		return `Name the workspace: /leverage login <workspace>. Yours: ${slugs}.`;
	}
	// Two workspaces may share a name, never a slug.
	const labels = workspaces.map((one) =>
		workspaces.filter((other) => other.name === one.name).length > 1
			? `${one.name} (${one.slug})`
			: one.name,
	);
	const picked = await $.ui
		.ask("Which Leverage workspace?", { header: "Leverage", options: labels })
		.catch(() => "");
	return workspaces[labels.indexOf(picked)] ?? "Sign-in stopped.";
}

// Trades the browser sign-in for a Claude Code token of one workspace.
async function trade(
	$: EngineInterface,
	url: string,
	access: string,
	named: string,
	live: () => boolean,
): Promise<string> {
	const listed = await send($, `${url}/api/workspaces`, undefined, access);
	if (!listed.ok) return `Leverage answered ${listed.status}.`;
	const workspaces = JSON.parse(listed.text) as Workspace[];
	if (workspaces.length === 0)
		return "Your Leverage account has no workspace yet.";
	const chosen = await choose($, workspaces, named);
	if (typeof chosen === "string") return chosen;
	if (!live()) return "";
	const minted = await send(
		$,
		`${url}/api/workspaces/${chosen.id}/claude/token`,
		{},
		access,
	);
	if (!minted.ok) return `Leverage answered ${minted.status}.`;
	return keep(
		$,
		url,
		(JSON.parse(minted.text) as { token: string }).token,
		live,
	);
}

// Asks every few seconds whether the person approved the code.
function awaitApproval(
	$: EngineInterface,
	url: string,
	grant: Grant,
	named: string,
) {
	let asked = 0;
	let skip = 0;
	let busy = false;
	const mine = attempt;
	const live = () => mine === attempt;
	const end = (text: string) => {
		timer.cancel();
		if (waiting === timer) waiting = null;
		if (live() && text) $.ui.toast(text, { timeoutMs: 8000 });
	};
	const timer = $.clock.every(grant.interval * 1000, async () => {
		if (busy) return;
		if (skip > 0) {
			skip--;
			return;
		}
		if (++asked * grant.interval > grant.expires_in)
			return end("The sign-in code expired. /leverage login starts again.");
		busy = true;
		try {
			// A code is good once, so its answer is always read to the end. A
			// network error leaves the code waiting: the next tick asks again.
			const res = await send($, `${url}/api/cli/auth/token`, {
				device_code: grant.device_code,
			}).catch(() => null);
			if (!res) return;
			// Not approved yet, or Leverage is busy: ask again later.
			if (res.status === 428 || res.status >= 500) return;
			if (res.status === 429) {
				skip = 1;
				return;
			}
			if (res.status === 410 && res.text.includes("denied"))
				return end("Sign-in denied.");
			if (res.status === 410 || res.status === 404)
				return end("The sign-in code expired. /leverage login starts again.");
			if (!res.ok) return end(`Leverage answered ${res.status}.`);
			timer.cancel();
			const { access_token } = JSON.parse(res.text) as {
				access_token: string;
			};
			end(await trade($, url, access_token, named, live));
		} catch (error) {
			end(`Leverage: ${(error as Error).message}`);
		} finally {
			busy = false;
		}
	});
	waiting = timer;
}

/** `/leverage login [workspace]`. A token is never typed: the transcript keeps commands. */
async function login($: EngineInterface, arg: string): Promise<string> {
	if (connectedBy() === "launched")
		return "This window runs with the token leverage claude started it with.";
	stopWaiting();
	if (!(await accessFile($))) return "No home folder to keep the token in.";
	const url = leverageHost(await $.env.get("LEVERAGE_HOST"));
	const started = await send($, `${url}/api/cli/auth/device`, {
		client_name: "Claude Code",
	});
	if (started.status === 429)
		return "Leverage asks you to wait a minute, then sign in again.";
	if (!started.ok) return `Leverage answered ${started.status}.`;
	const grant = JSON.parse(started.text) as Grant;
	const link = `${url}/device?user_code=${encodeURIComponent(grant.user_code)}`;
	await browse($, link);
	awaitApproval($, url, grant, arg);
	return `Confirm ${grant.user_code} in the browser: ${link}`;
}

/** `/leverage logout`: forgets the token and leaves Leverage in this window. */
async function logout($: EngineInterface): Promise<string> {
	if (connectedBy() === "launched")
		return "This window runs with the token leverage claude started it with.";
	stopWaiting();
	const file = await accessFile($);
	if (file && (await $.fs.exists(file).catch(() => false))) {
		const removed = await $.process.run(["rm", "-f", file]).catch(() => null);
		if (removed?.exitCode !== 0) await $.fs.write(file, "{}\n");
	}
	disconnect();
	await $.ui.close({ id: PANE }).catch(() => {});
	$.ui.status(undefined);
	// The token itself ends only when Leverage revokes it.
	const revoke = "Leverage Settings → Integrations revokes the token.";
	return (await cliHasToken($))
		? `Signed out here. ${revoke} The Leverage CLI keeps its own: leverage logout ends it.`
		: `Signed out. ${revoke}`;
}

export function registerCommands(on: On) {
	on("command.run", { command: "leverage" }, async ($, e) => {
		const [action = "", ...rest] = e.args.trim().split(/\s+/);
		try {
			if (action === "login") return { text: await login($, rest.join(" ")) };
			if (action === "logout") return { text: await logout($) };
		} catch (error) {
			return { text: `Leverage: ${(error as Error).message}` };
		}
		if (!isReachable())
			return { text: "Not signed in to Leverage. /leverage login signs in." };
		if (!e.args.trim()) {
			await $.ui.open({ id: PANE, title: "Leverage" });
			return { text: "Leverage pane opened. /leverage help lists the rest." };
		}
		try {
			return { text: await run($, e.args) };
		} catch (error) {
			return { text: `Leverage: ${(error as Error).message}` };
		}
	});
}

